import React, { Component } from 'react';
import axios from 'axios';
import MyContext from '../contexts/MyContext';

class VoucherComponent extends Component {
  static contextType = MyContext;

  constructor(props) {
    super(props);
    this.state = {
      vouchers: [],
      txtCode: '',
      txtDiscountValue: '',
      txtMinOrderValue: '0',
      txtExpiryDate: '',
      cmbStatus: 'Active'
    };
  }

  componentDidMount() {
    this.apiGetVouchers();
  }

  // Lấy danh sách Voucher từ Server
  apiGetVouchers = () => {
    const config = { headers: { 'x-access-token': this.context.token } };
    axios.get('/api/admin/vouchers', config).then((res) => {
      this.setState({ vouchers: res.data });
    });
  };

  // Reset Form
  resetForm = () => {
    this.setState({
      txtCode: '',
      txtDiscountValue: '',
      txtMinOrderValue: '0',
      txtExpiryDate: '',
      cmbStatus: 'Active'
    });
  };

  // Thêm mới Voucher
  btnSaveClick = (e) => {
    e.preventDefault();
    const { txtCode, txtDiscountValue, txtMinOrderValue, txtExpiryDate, cmbStatus } = this.state;

    if (!txtCode || !txtDiscountValue) {
      alert('Vui lòng nhập Mã giảm giá và Giá trị giảm!');
      return;
    }

    const voucher = {
      code: txtCode.toUpperCase().trim(),
      discountValue: parseInt(txtDiscountValue),
      minOrderValue: parseInt(txtMinOrderValue || 0),
      expiryDate: txtExpiryDate ? new Date(txtExpiryDate) : null,
      status: cmbStatus
    };

    const config = { headers: { 'x-access-token': this.context.token } };

    axios.post('/api/admin/vouchers', voucher, config).then((res) => {
      if (res.data) {
        alert('Tạo mã giảm giá mới thành công!');
        this.apiGetVouchers();
        this.resetForm();
      }
    }).catch((err) => {
      alert('Lỗi tạo voucher (Mã giảm giá có thể đã tồn tại)!');
    });
  };

  // Xóa Voucher
  btnDeleteClick = (id) => {
    if (window.confirm('Bạn có chắc chắn muốn xóa mã giảm giá này?')) {
      const config = { headers: { 'x-access-token': this.context.token } };
      axios.delete(`/api/admin/vouchers/${id}`, config).then((res) => {
        if (res.data.success) {
          alert('Đã xóa mã giảm giá!');
          this.apiGetVouchers();
        }
      });
    }
  };

  render() {
    const { vouchers, txtCode, txtDiscountValue, txtMinOrderValue, txtExpiryDate, cmbStatus } = this.state;

    return (
      <div style={{ padding: '20px' }}>
        <h3 style={{ color: '#4A2E2B', marginBottom: '20px' }}>QUẢN LÝ MÃ GIẢM GIÁ (VOUCHER)</h3>
        <div style={{ display: 'flex', gap: '30px' }}>
          
          {/* Cột trái: Form tạo Voucher */}
          <div style={{ flex: '1', backgroundColor: '#FFF', padding: '20px', borderRadius: '12px', boxShadow: '0 2px 8px rgba(0,0,0,0.05)' }}>
            <h4 style={{ marginBottom: '15px' }}>Tạo mã giảm giá mới</h4>
            <form>
              <div style={{ marginBottom: '12px' }}>
                <label style={{ display: 'block', marginBottom: '5px' }}>Mã giảm giá (CODE) *</label>
                <input
                  type="text"
                  style={{ width: '100%', padding: '8px', borderRadius: '6px', border: '1px solid #ccc', textTransform: 'uppercase' }}
                  value={txtCode}
                  onChange={(e) => this.setState({ txtCode: e.target.value })}
                  placeholder="VD: VANLANG10, SALE50K..."
                />
              </div>

              <div style={{ marginBottom: '12px' }}>
                <label style={{ display: 'block', marginBottom: '5px' }}>Giá trị giảm (VNĐ) *</label>
                <input
                  type="number"
                  style={{ width: '100%', padding: '8px', borderRadius: '6px', border: '1px solid #ccc' }}
                  value={txtDiscountValue}
                  onChange={(e) => this.setState({ txtDiscountValue: e.target.value })}
                  placeholder="VD: 20000, 50000"
                />
              </div>

              <div style={{ marginBottom: '12px' }}>
                <label style={{ display: 'block', marginBottom: '5px' }}>Đơn hàng tối thiểu (VNĐ)</label>
                <input
                  type="number"
                  style={{ width: '100%', padding: '8px', borderRadius: '6px', border: '1px solid #ccc' }}
                  value={txtMinOrderValue}
                  onChange={(e) => this.setState({ txtMinOrderValue: e.target.value })}
                  placeholder="VD: 100000"
                />
              </div>

              <div style={{ marginBottom: '12px' }}>
                <label style={{ display: 'block', marginBottom: '5px' }}>Ngày hết hạn</label>
                <input
                  type="date"
                  style={{ width: '100%', padding: '8px', borderRadius: '6px', border: '1px solid #ccc' }}
                  value={txtExpiryDate}
                  onChange={(e) => this.setState({ txtExpiryDate: e.target.value })}
                />
              </div>

              <div style={{ marginBottom: '20px' }}>
                <label style={{ display: 'block', marginBottom: '5px' }}>Trạng thái</label>
                <select
                  style={{ width: '100%', padding: '8px', borderRadius: '6px', border: '1px solid #ccc' }}
                  value={cmbStatus}
                  onChange={(e) => this.setState({ cmbStatus: e.target.value })}
                >
                  <option value="Active">Hoạt động (Active)</option>
                  <option value="Inactive">Tạm khóa (Inactive)</option>
                </select>
              </div>

              <button
                type="submit"
                onClick={this.btnSaveClick}
                style={{ width: '100%', backgroundColor: '#4A2E2B', color: '#FFF', padding: '10px', border: 'none', borderRadius: '6px', cursor: 'pointer', fontWeight: 'bold' }}
              >
                TẠO MÃ GIẢM GIÁ
              </button>
            </form>
          </div>

          {/* Cột phải: Bảng danh sách Voucher */}
          <div style={{ flex: '2', backgroundColor: '#FFF', padding: '20px', borderRadius: '12px', boxShadow: '0 2px 8px rgba(0,0,0,0.05)' }}>
            <h4 style={{ marginBottom: '15px' }}>Danh sách mã giảm giá phát hành</h4>
            <table style={{ width: '100%', borderCollapse: 'collapse', textAlign: 'left' }}>
              <thead>
                <tr style={{ backgroundColor: '#F4EBE1', borderBottom: '2px solid #DDD' }}>
                  <th style={{ padding: '10px' }}>Mã CODE</th>
                  <th style={{ padding: '10px' }}>Mức giảm</th>
                  <th style={{ padding: '10px' }}>Đơn tối thiểu</th>
                  <th style={{ padding: '10px' }}>Hạn sử dụng</th>
                  <th style={{ padding: '10px' }}>Trạng thái</th>
                  <th style={{ padding: '10px' }}>Hành động</th>
                </tr>
              </thead>
              <tbody>
                {vouchers.map((item) => (
                  <tr key={item._id} style={{ borderBottom: '1px solid #EEE' }}>
                    <td style={{ padding: '10px', fontWeight: 'bold', color: '#C85A32' }}>{item.code}</td>
                    <td style={{ padding: '10px', fontWeight: 'bold' }}>
                      -{item.discountValue ? item.discountValue.toLocaleString('vi-VN') + ' đ' : '0 đ'}
                    </td>
                    <td style={{ padding: '10px' }}>
                      {item.minOrderValue ? item.minOrderValue.toLocaleString('vi-VN') + ' đ' : '0 đ'}
                    </td>
                    <td style={{ padding: '10px', fontSize: '13px' }}>
                      {item.expiryDate ? new Date(item.expiryDate).toLocaleDateString('vi-VN') : 'Không giới hạn'}
                    </td>
                    <td style={{ padding: '10px' }}>
                      <span style={{
                        padding: '4px 8px', borderRadius: '12px', fontSize: '12px', color: '#FFF',
                        backgroundColor: item.status === 'Active' ? '#2E7D32' : '#C62828'
                      }}>
                        {item.status === 'Active' ? 'Hoạt động' : 'Đã khóa'}
                      </span>
                    </td>
                    <td style={{ padding: '10px' }}>
                      <button
                        onClick={() => this.btnDeleteClick(item._id)}
                        style={{ backgroundColor: '#D32F2F', color: '#FFF', border: 'none', padding: '4px 10px', borderRadius: '4px', cursor: 'pointer' }}
                      >
                        Xóa
                      </button>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>

        </div>
      </div>
    );
  }
}

export default VoucherComponent;
